-- NextSkill Institute starter schema (run in Supabase SQL Editor)
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','teacher','student');
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', email text not null default '', role public.app_role not null default 'student', phone text, created_at timestamptz not null default now());
create table if not exists public.courses (id uuid primary key default gen_random_uuid(), title text not null, category text not null default 'General', description text not null default '', duration text not null default '', fee numeric(10,2) not null default 0, level text not null default 'Beginner', is_published boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.admissions (id uuid primary key default gen_random_uuid(), full_name text not null, email text not null, phone text not null, course_id uuid references public.courses(id) on delete set null, course_title text not null default '', education text, message text, status text not null default 'new' check(status in ('new','contacted','approved','rejected')), created_at timestamptz not null default now());
create table if not exists public.enrollments (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id) on delete cascade, course_id uuid not null references public.courses(id) on delete restrict, status text not null default 'active', enrolled_at timestamptz not null default now(), unique(student_id,course_id));
create table if not exists public.fee_payments (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id) on delete cascade, course_id uuid references public.courses(id) on delete set null, amount numeric(10,2) not null check(amount>=0), payment_method text not null default 'cash', reference text, paid_at timestamptz not null default now());
create table if not exists public.attendance (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id) on delete cascade, course_id uuid references public.courses(id) on delete set null, attendance_date date not null default current_date, status text not null check(status in ('present','absent','late')), marked_by uuid references public.profiles(id), unique(student_id,course_id,attendance_date));
create table if not exists public.study_materials (id uuid primary key default gen_random_uuid(), course_id uuid references public.courses(id) on delete cascade, title text not null, file_url text not null, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.announcements (id uuid primary key default gen_random_uuid(), title text not null, body text not null, published boolean not null default false, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('admin','teacher')); $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.courses enable row level security; alter table public.admissions enable row level security; alter table public.enrollments enable row level security; alter table public.fee_payments enable row level security; alter table public.attendance enable row level security; alter table public.study_materials enable row level security; alter table public.announcements enable row level security;
drop policy if exists "profiles read own or staff" on public.profiles; create policy "profiles read own or staff" on public.profiles for select to authenticated using(id=auth.uid() or public.is_staff());
drop policy if exists "admins manage profiles" on public.profiles; create policy "admins manage profiles" on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "published courses public read" on public.courses; create policy "published courses public read" on public.courses for select to anon,authenticated using(is_published or public.is_staff());
drop policy if exists "staff manage courses" on public.courses; create policy "staff manage courses" on public.courses for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists "public submit admissions" on public.admissions; create policy "public submit admissions" on public.admissions for insert to anon,authenticated with check(true);
drop policy if exists "staff manage admissions" on public.admissions; create policy "staff manage admissions" on public.admissions for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists "student read own enrollments" on public.enrollments; create policy "student read own enrollments" on public.enrollments for select to authenticated using(student_id=auth.uid() or public.is_staff());
drop policy if exists "staff manage enrollments" on public.enrollments; create policy "staff manage enrollments" on public.enrollments for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists "student read own payments" on public.fee_payments; create policy "student read own payments" on public.fee_payments for select to authenticated using(student_id=auth.uid() or public.is_staff());
drop policy if exists "staff manage payments" on public.fee_payments; create policy "staff manage payments" on public.fee_payments for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists "student read own attendance" on public.attendance; create policy "student read own attendance" on public.attendance for select to authenticated using(student_id=auth.uid() or public.is_staff());
drop policy if exists "staff manage attendance" on public.attendance; create policy "staff manage attendance" on public.attendance for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists "enrolled students read materials" on public.study_materials; create policy "enrolled students read materials" on public.study_materials for select to authenticated using(public.is_staff() or exists(select 1 from public.enrollments e where e.student_id=auth.uid() and e.course_id=study_materials.course_id));
drop policy if exists "staff manage materials" on public.study_materials; create policy "staff manage materials" on public.study_materials for all to authenticated using(public.is_staff()) with check(public.is_staff());
drop policy if exists "published announcements read" on public.announcements; create policy "published announcements read" on public.announcements for select to anon,authenticated using(published or public.is_staff());
drop policy if exists "staff manage announcements" on public.announcements; create policy "staff manage announcements" on public.announcements for all to authenticated using(public.is_staff()) with check(public.is_staff());
